import { Component, Element, h, Host, Listen, Prop } from '@stencil/core';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

@Component({
  tag: 'groupui-icon-button',
  styleUrl: 'icon-button.scss',
  shadow: true,
})
export class IconButton {
  /**
   * variant of the icon button
   */
  @Prop({ reflect: true }) readonly variant: 'base' | 'inverted' | 'weak' = 'base';

  /**
   * icon name e.g. 'clock-16'. Use the icon sizes 16px only
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-16.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * disabled status of the icon button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * toggled status of the icon button
   */
  @Prop({ reflect: true }) readonly toggled: boolean;

  @Element() host: HTMLElement;

  private ariaAttributes: AriaAttributes;

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Enter' || event.code === 'Space') {
      event.preventDefault();
    }
  }

  @Listen('keyup')
  onKeyUp(event: KeyboardEvent) {
    if (event.code === 'Enter' || event.code === 'Space') {
      this.host.dispatchEvent(new window.Event('click', { bubbles: true }));
    }
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  render() {
    return (
      <Host>
        <button aria-label="Icon" {...this.ariaAttributes} disabled={this.disabled} tabIndex={0}>
          <groupui-icon name={this.icon} src={this.iconSource} aria-hidden="true" />
        </button>
      </Host>
    );
  }
}
